  print(\"text\",repr(str(x)[:120]),\"tag\",x.parent.name)
  p=x
  for i in range(5):
   p=p.parent
   if p is None: break
   print(i+1,p.name,p.get(\"class\"),len(p.get_text(\" \",strip=True)))
  break'"

